namespace LinkUp.Api.Data.Entities;

/// <summary>A real place in the curated dataset. All money values are in euros.</summary>
public sealed class Venue
{
    /// <summary>The id from the dataset (not generated by the database).</summary>
    public int Id { get; set; }
    public required string Name { get; set; }
    public VenueCategory Category { get; set; }
    public required string Address { get; set; }
    public double Latitude { get; set; }
    public double Longitude { get; set; }

    public EntranceType EntranceType { get; set; }
    /// <summary>Null when unknown or event-dependent.</summary>
    public decimal? EntranceFee { get; set; }
    /// <summary>Typical spend per person when consuming.</summary>
    public decimal? MinSpend { get; set; }
    public decimal? MaxSpend { get; set; }
    /// <summary>1 = cheap … 4 = expensive. Derived from the spend range at import.</summary>
    public int PriceLevel { get; set; }

    public string? Notes { get; set; }
    public List<string> Tags { get; set; } = [];

    /// <summary>False hides the venue from plan generation without deleting it.</summary>
    public bool IsActive { get; set; } = true;

    public List<VenueOpeningHours> OpeningHours { get; set; } = [];
}